W += [
E('fix','/fɪks/','修理；解决；固定；确定；安排、准备；操纵；解决办法、困境〔名词〕','核心画面是把东西放到确定、稳妥的位置：坏的修好，时间定下，零件固定，问题处理掉。','接拉丁 fixus，是 figere“钉住、固定”的分词；通常推测经古法语 *fixer 进入中古英语，* 表示重建形式。',FIX,'fix a bike 是修车；fix a date 是定日期；fix a shelf to the wall 是固定架子。美式 fix dinner 是准备晚饭。fix a match 则是操纵赛果；a quick fix 是应急办法，in a fix 是陷入困境。','fix a problem；fix a date；fix something to；a quick fix；in a fix。','repair 主要修复损坏；fix 更口语、更广，时间、规则、饭菜、结果都可能成为宾语。',('Can you fix the broken lock?','你能修好这把坏锁吗？'),('We fixed a date for the next meeting.','我们定下了下次会议的日期。'),('This patch is a quick fix, not a permanent solution.','这个补丁是临时办法，还不是长久的解决方案。'),('The investigation found that the match had been fixed.','调查发现比赛结果遭到了操纵。'),sources=['https://www.etymonline.com/word/fix','https://www.oxfordlearnersdictionaries.com/definition/english/fix_1']),
E('fixed','/fɪkst/','固定的；不变的；确定好的；被操纵的','位置、金额、时间或结果已经被钉住，不能随意变动。','fix + -ed，/s/ 后的 -ed 读 /t/；英语很早就把这个分词用于固定、不变的状态。',FIX+[['英语 fix → fixed','固定 → 不变、已确定；也可指已修好、被操纵']],'a fixed price 是固定价格；a fixed schedule 是固定日程；a fixed smile 则是保持不动、可能不自然的笑容。The game was fixed 表示赛果被操纵，不是游戏修好了。','a fixed price；fixed costs；a fixed schedule；a fixed smile。','stable 说相对稳定；fixed 更强调已经确定、不作变动。fixed costs 在特定业务范围内也不随产量直接变化。',('The course has a fixed start date.','这门课程的开课日期是固定的。'),('She listened with a fixed smile on her face.','她听着，脸上一直挂着僵硬的笑容。'),sources=['https://www.etymonline.com/word/fixed','https://www.oxfordlearnersdictionaries.com/definition/english/fixed']),
E('fixing','/ˈfɪksɪŋ/','修理；固定；确定；操纵；固定配件〔常用复数〕','要看后面接什么：修水管、定价格、把东西装牢，都是不同的 fixing。','fix + -ing，表示动作或过程；名词复数 fixings 还可指固定配件，美式口语也可指配菜、附件。',FIX+[['英语 fix → fixing / fixings','修理、固定等过程；固定用的配件或配套东西']],'fixing the roof 是修屋顶；price fixing 通常指操纵价格的安排，不只是正常标价。英国商品说明里的 fixings 往往是螺钉、支架等安装配件。','fixing a fault；price fixing；wall fixings；all the fixings。','fixed 描述已经定住的状态；fixing 描述动作，或执行固定作用的配件。',('Fixing the leak took longer than expected.','修好漏水处花的时间比预计长。'),('The shelf comes with all the necessary fixings.','这个架子附带了全部必要的安装配件。'),sources=['https://www.merriam-webster.com/dictionary/fixing','https://www.oxfordlearnersdictionaries.com/definition/english/fixings']),
E('fixture','英 /ˈfɪkstʃə/；美 /ˈfɪkstʃər/','固定装置；常驻人物；预定赛事','原本是装在某处不轻易移走的东西；人长期总出现，也像成了固定陈设。','与 fixure“固定物”等旧形式有关，拼写受 mixture 一类形式影响；不能因此凭空造出拉丁 *fixtum。',FIX+[['英语 fixure / fixture','固定行为、固定物；fixture 的形式受 mixture 等类推影响'],['现代英语 fixture','固定装置；常驻人物；预定比赛']],'a light fixture 是灯具安装装置；a fixture at the café 说某人总在咖啡馆出现。英式 sports fixtures 是赛程里的预定比赛，像已经钉在日历上。','lighting fixtures；a permanent fixture；a home fixture；a fixture list。','furniture 通常是可移动家具；fixtures 常与建筑安装相连。体育 fixture 是一次已安排的比赛，不是体育器材。',('The room needs new lighting fixtures.','房间需要新的照明灯具。'),('He has become a fixture at the village café.','他已经成了村里咖啡馆的常客。'),('The club announced its fixtures for the coming season.','俱乐部公布了下个赛季的赛程。'),sources=['https://www.etymonline.com/word/fixture','https://www.oxfordlearnersdictionaries.com/definition/english/fixture']),
E('fixation','/fɪkˈseɪʃən/','执着；迷恋；固定、固着','注意力像被钉在一点上，反复绕着同一个人、问题或想法转。','来自中世纪拉丁 fixatio，亦有经法语 fixation 的路线；早期有使物质固定、稳定的义，远早于英语动词 fixate。',FIXATION,'a fixation on appearance 是对外貌过分执着；普通使用不等于在作医学诊断。科学里的 fixation 还可能是把物质固定为特定形式，必须按领域理解。','a fixation on；develop a fixation；an unhealthy fixation。','focus 可以是有用、可调整的专注；fixation 常暗示过分黏住某点、难以转移。',('His fixation on minor details delayed the project.','他对细枝末节的执着拖慢了项目。'),('The novel explores the character’s fixation on the past.','小说探讨了这个人物对过去的执迷。'),sources=['https://www.etymonline.com/word/fixation','https://www.oxfordlearnersdictionaries.com/definition/english/fixation']),
E('fixate','英 /fɪkˈseɪt/；美 /ˈfɪkseɪt/','过分关注；执着于；把视线固定在','目光或心思一直钉在一个点上，很难挪开。','fix + -ate 或接拉丁 fixus 构词；心理意义可能也从更早的 fixation 反构，不把名词都排在动词之后。',FIXATE,'日常常用 fixate on：不要一直纠结小错误。视觉研究中的 fixate a target 则可以仅指注视目标，没有负面情绪。英美常见重音位置不同。','fixate on a mistake；fixate on the past；fixate a visual target。','concentrate 强调集中注意力；fixate 在普通话语里常带过度、难以放下的意思。',('Try not to fixate on the one question you answered badly.','尽量不要一直纠结那一道没答好的题。'),('Participants were asked to fixate a dot at the centre of the screen.','研究要求参与者注视屏幕中央的一个点。'),sources=['https://www.etymonline.com/word/fixate','https://www.oxfordlearnersdictionaries.com/definition/english/fixate']),
E('fixated','英 /fɪkˈseɪtɪd/；美 /ˈfɪkseɪtɪd/','执着于的；过度迷恋的','心思已经被某个对象占住，讨论别的事又会绕回来。','fixate + -ed；常用 be fixated on，表示持续过分关注的状态。',FIXATE+[['英语 fixate → fixated','把注意力定住 → 对某事过分执着的']],'fixated on success 是一门心思盯着成功；fixated on a detail 是被细节困住。这个词通常不只是表扬认真，而是提醒关注失衡。','be fixated on；remain fixated on；become fixated on。','interested in 是感兴趣；fixated on 通常强得多，暗示难以把心思转向其他地方。',('The team became fixated on the deadline and ignored the quality problems.','团队只顾盯着期限，忽略了质量问题。'),('She is still fixated on a comment he made years ago.','她仍对他多年前的一句评论耿耿于怀。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/fixated','https://www.etymonline.com/word/fixate']),
E('fixer','英 /ˈfɪksə/；美 /ˈfɪksər/','善于摆平事情的人；协调人；定影剂〔专业〕','遇到麻烦时，能找到人、安排资源、把事情办成的那个人。','fix + -er；人物义来自处理、安排事情，摄影中的材料义接使影像固定的作用。',FIX+[['英语 fix + -er → fixer','安排、处理 → 能把事办成的人；固定作用的材料']],'a political fixer 常暗示靠关系运作，可能不光彩；新闻或摄制团队的 local fixer 则可中性指安排采访、交通和联络的人。摄影里的 fixer 是另一种具体工作材料。','a political fixer；a local fixer；work as a fixer。','repairer 主要修坏东西；fixer 常解决组织、人际和安排上的麻烦，不只是修理工。',('The crew hired a local fixer to arrange interviews and transport.','摄制组雇了一名当地协调人，安排采访和交通。'),('The novel centres on a fixer who knows everyone in city politics.','小说围绕一个熟悉城里所有政治人物的掮客展开。'),sources=['https://www.etymonline.com/word/fixer','https://www.oxfordlearnersdictionaries.com/definition/english/fixer']),
E('fixable','/ˈfɪksəbəl/','可以修好的；可以解决的','问题确实存在，但还有办法处理，不是已经无可挽回。','fix + -able；直接由现代动词的修理、解决义派生。',FIX+[['英语 fix + -able → fixable','修好、解决 → 能够修好、解决的']],'a fixable fault 是可修复的故障；a fixable mistake 是可补救的错误。只说明存在办法，不表示一定便宜、容易或立刻能完成。','a fixable problem；a fixable fault；easily fixable。','fixed 是已经解决；fixable 只是有解决的可能。',('The mechanic said the fault was fixable.','修理师说这个故障可以修好。'),('The report contains several easily fixable errors.','报告中有几个很容易纠正的错误。'),sources=['https://www.merriam-webster.com/dictionary/fixable','https://en.wiktionary.org/wiki/fixable#English']),
E('prefix','名词 /ˈpriːfɪks/；动词常 /ˈpriːfɪks/，亦 /priːˈfɪks/','前缀；放在前面的部分；在前面加','把一个有作用的小部分接到词或字符串前面。','名词接拉丁 praefixum，来自动词 praefigere：prae-“前” + figere“固定”；英语动词经法语 prefixer 等进入，记录反而早于语法名词。',[['拉丁语 prae- + figere → praefigere / praefixus','在前 + 固定 → 放在前面'],['分支一：拉丁语 praefixum → 英语 prefix〔名词〕','接在前面的部分 → 前缀'],['并列分支二：法语 prefixer → 中古英语 prefixen → prefix〔动词〕','预先确定 → 把东西加在前面']],'unhappy 的 un- 是 prefix；编号前的字母也可叫 prefix。动词可说 prefix a name with a code，把代码放到名字前。不是所有开头相同的字母都是词源上的前缀。','add a prefix；a telephone prefix；prefix something with。','suffix 接后面；prefix 接前面；affix 是更一般的词缀名称。',('The prefix “un-” changes the meaning of “happy”.','前缀 un- 改变了 happy 的意思。'),('Prefix each filename with the project code.','在每个文件名前加上项目代码。'),sources=['https://www.etymonline.com/word/prefix','https://www.oxfordlearnersdictionaries.com/definition/english/prefix_2','https://en.wiktionary.org/wiki/prefix#English']),
E('affix','名词 /ˈæfɪks/；动词 /əˈfɪks/','词缀；附加物；粘上、贴上','把某个部分接到另一东西上：可以是信封上的标签，也可以是词里的词缀。','拉丁 ad- 在 f 前同化为 af-，与 figere 组成 affigere；英语动词经中世纪拉丁 affixare 或法语 affixer，名词也可能经法语 affixe 借入。',[['拉丁语 ad- + figere → affigere / affixus','朝向 + 固定 → 附着、固定在上面'],['中世纪拉丁语 affixare / 法语 affixer → 英语 affix〔动词〕','使附着 → 贴上、加上'],['英语名词 affix〔由动词或法语 affixe〕','附加部分 → 词缀']],'动词 affix a label to a box 是把标签贴到盒子上，语气比 stick 正式。名词 affix 包含 prefix、suffix 等类型。注意名词前重音、动词后重音。','affix a label to；affix a stamp；a derivational affix。','prefix 与 suffix 指定位置；affix 更概括。attach 更通用，affix 常有牢牢贴上、加上的感觉。',('Affix the label to the outside of the package.','把标签贴在包裹外面。'),('The lesson explains how an affix can change a word’s meaning.','这一课解释了词缀如何改变一个词的意思。'),sources=['https://www.etymonline.com/word/affix','https://www.oxfordlearnersdictionaries.com/definition/english/affix_1','https://www.oxfordlearnersdictionaries.com/definition/english/affix_2']),
E('hotfix','英 /ˈhɒtfɪks/；美 /ˈhɑːtfɪks/','紧急修复；针对具体问题的快速补丁','等不到下一次常规发布，先把一个急迫的软件问题修掉。','hot“急迫、即时处理的” + fix“修复”；软件领域的现代复合词，不是把设备加热。',FIX+[['英语 hot + fix → hotfix','即时、紧急 + 修复 → 针对问题快速发布的补丁']],'release a hotfix 是发布紧急补丁；apply a hotfix 是应用它。不同产品对发布方式的定义略有差别，不保证一定无需重启，也不保证涵盖所有改动。','release a hotfix；apply a hotfix；a security hotfix。','patch 是补丁总称；hotfix 通常突出紧急、针对性强，release 则可包含功能等更广变化。',('The developers released a hotfix for the login failure.','开发者为登录失败问题发布了紧急修复。'),('The team tested the hotfix before deploying it.','团队在部署前测试了这个紧急补丁。'),sources=['https://www.merriam-webster.com/dictionary/hotfix','https://en.wiktionary.org/wiki/hotfix#English']),
E('transfix','/trænsˈfɪks/','使呆住；使出神；刺穿〔字面〕','像被一根看不见的钉子定在原地，眼睛挪不开，身体也一时不动。','拉丁 trans-“穿过” + figere“刺入、固定”构成 transfigere，分词 transfixus，经法语 transfixer 进入英语。',TRANS,'现代阅读里常是 be transfixed by a sight：因为惊讶、恐惧或着迷而呆住。早期的实际刺穿义解释了“钉在原地”的比喻，但使用时不需要真实受伤。','transfix an audience；be transfixed by；transfix with fear。','interest 只是引起兴趣；transfix 强调强烈到让人暂时僵住、完全被吸住。',('The strange light transfixed everyone in the room.','那道奇异的光让屋里所有人都看呆了。'),('The performer seemed able to transfix an entire audience.','那位表演者似乎能让全场观众都看得出神。'),sources=['https://www.etymonline.com/word/transfix','https://www.oxfordlearnersdictionaries.com/definition/english/transfix']),
E('transfixed','/trænsˈfɪkst/','看呆的；出神的；僵住的','整个人的注意力被牢牢吸住，像突然停在原地。','transfix + -ed，末尾读 /kst/；常用作分词形容词，说明被某种景象、情绪定住的状态。',TRANS+[['英语 transfix → transfixed','使呆住 → 已经看呆、出神的']],'stand transfixed 是站着看呆了；transfixed by fear 是恐惧得僵住。它可以来自美景、表演或惊恐，不只是“吓坏”。','stand transfixed；watch transfixed；be transfixed by。','fixated 常是持续过度执着于某个对象；transfixed 更像当下的一次震撼、出神或僵住。',('The children stood transfixed by the fireworks.','孩子们站在那里，看烟花看得入了神。'),('She remained transfixed, unable to look away from the screen.','她一直看得出神，无法把目光从屏幕上移开。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/transfixed','https://www.etymonline.com/word/transfix']),
]
IMMIGRATE=IM+[['拉丁语 immigratus → 英语 immigrate','迁入的分词形式 → 迁入某国定居']]
EMIGRATION=EM+[['晚期拉丁语 emigratio → 英语 emigration','迁出行动 → 离开原居国或地区定居别处']]
EMIGRATE=EM+[['两种可能近源：拉丁语 emigratus；或英语 emigration 反构','都指向离开原居地'],['英语 emigrate','迁出原国家或地区，在别处定居']]
W += [
E('migrate','/maɪˈɡreɪt/，亦 /ˈmaɪɡreɪt/','迁移；迁徙；转移数据、系统','把原来生活、停留或运行的地方换到另一处。','借自拉丁 migratus，接 migrare“从一处搬到另一处”；现代英语的 -ate 是承接古典词形，不是从 migrant 简单去尾。',MIGRATE,'鸟类 migrate 是迁徙，人可以为了工作迁居；软件也可 migrate to a new platform。技术用法还可直接接宾语：migrate the data，把数据迁过去。','migrate south；migrate from…to…；migrate data；migrate to a new platform。','emigrate 看迁出，immigrate 看迁入；migrate 更概括，也适用于动物、数据等，不限定国界。',('These birds migrate south in autumn.','这些鸟秋天向南迁徙。'),('The team plans to migrate the data to a new server.','团队计划把数据迁移到新服务器。'),sources=['https://www.etymonline.com/word/migrate','https://www.oxfordlearnersdictionaries.com/definition/english/migrate']),
E('migration','/maɪˈɡreɪʃən/','迁移；迁徙；移民流动；数据迁移','把许多次移动或一次完整搬迁过程当成一个现象来观察。','拉丁 migratio 经法语或直接进入英语，接 migrare；英语名词记录早于常见动词 migrate，不能只按现代动词加 -ion 写历史。',MIGRATION,'bird migration 是鸟类迁徙；rural-to-urban migration 是从乡村向城市的人口迁移；data migration 是数据搬到新环境的过程。迁移可以在一国内发生，也可以跨国。','seasonal migration；internal migration；data migration；migration patterns。','immigration 特别从迁入地观察人口移动；migration 是更广的总称，不自带“外国人”判断。',('The wetlands are an important stop during bird migration.','这些湿地是鸟类迁徙途中重要的停歇地。'),('The report tracks migration from rural areas to cities.','报告追踪了从农村到城市的人口迁移。'),('Data migration will take place over the weekend.','数据迁移将在周末进行。'),sources=['https://www.etymonline.com/word/migration','https://www.oxfordlearnersdictionaries.com/definition/english/migration']),
E('migrant','/ˈmaɪɡrənt/','迁移者；外来务工者；迁徙动物；迁移的','生活或工作地点从一处转到另一处的人；也可以说季节性迁徙的动物。','接拉丁 migrans、migrant-，是 migrare 的现在分词，亦有法语 migrant 的借入路线；英语先有形容词，后来常作人物名词。',M+[['拉丁语 migrans / migrant-，可能经法语 migrant → 英语 migrant〔形容词〕','正在迁移的 → 迁移的、流动的'],['英语 migrant〔名词〕','迁移者；迁徙动物']],'migrant workers 常指为工作迁到别处的人，不必跨国；a summer migrant 可以指夏季来此的候鸟。是否永久定居、为何迁移，要看具体描述。','migrant workers；a migrant community；a summer migrant。','immigrant 更突出迁入一个国家定居；migrant 范围更广。refugee 则涉及逃离迫害、冲突等的特定处境，不能凭词形互相替代。',('The harvest depends on seasonal migrant workers.','收获季需要依靠季节性流动工人。'),('This bird is a summer migrant to the region.','这种鸟是夏季迁到该地区的候鸟。'),sources=['https://www.etymonline.com/word/migrant','https://www.oxfordlearnersdictionaries.com/definition/english/migrant']),
E('migratory','英 /ˈmaɪɡrətri/，亦 /maɪˈɡreɪtəri/；美 /ˈmaɪɡrətɔːri/','迁徙的；迁移性的','按季节或生存需要换地方活动，而不是总待在同一区域。','接拉丁 migrat- 词干与 -ory 一系，也可联系拉丁 migratorius；现代与 migrate 对应，描述迁徙习性或过程。',MIGRATORY,'migratory birds 是候鸟；migratory routes 是迁徙路线。也可用于工作人口等流动现象，不能只等同于“会飞的”。同一种动物的不同种群可能有不同迁徙习性。','migratory birds；migratory routes；migratory behaviour。','mobile 只说能移动；migratory 常说有迁移、迁徙习性或规律，不是每次挪动都算迁徙。',('The island provides shelter for migratory birds.','这座岛为候鸟提供了栖息处。'),('Researchers mapped the animals’ migratory routes.','研究人员绘制了这些动物的迁徙路线。'),sources=['https://www.etymonline.com/word/migratory','https://www.oxfordlearnersdictionaries.com/definition/english/migratory']),
E('nonmigratory','美 /ˌnɑːnˈmaɪɡrətɔːri/','不迁徙的；非迁移性的','在这里谈的种群通常留在本地，而不进行规律性的季节远行。','non-“不、非” + migratory；是英语透明否定构词。',MIGRATORY+[['英语 non- + migratory → nonmigratory','不 + 迁徙的 → 不迁徙的']],'nonmigratory birds 通常指留鸟或不作季节迁徙的种群；不表示它们从不飞走、扩散或寻找食物。描述的范围可以是某个种群，而非整个物种。','a nonmigratory population；nonmigratory birds；a nonmigratory species。','sedentary 在生态语境可近似说留居；在人身上还常指久坐。nonmigratory 专门否定迁徙，不等于完全不动。',('The study compares migratory and nonmigratory populations.','研究比较了迁徙种群和不迁徙种群。'),('The reserve supports several nonmigratory bird species throughout the year.','这片保护区全年为几种留鸟提供生存环境。'),sources=['https://www.merriam-webster.com/dictionary/nonmigratory','https://en.wiktionary.org/wiki/nonmigratory#English']),
E('immigrate','/ˈɪmɪɡreɪt/','移居入境；迁入另一国家定居','站在目的地这一边看：有人从外面搬进来，准备在这里生活。','拉丁 in-“进入”在 m 前同化为 im-，与 migrare 构成 immigrare；英语接其分词 immigratus。',IMMIGRATE,'常说 immigrate to a country，也可以补 from 原居地。重点是迁入并居住，不是短期旅游、出差或普通一次入境。','immigrate to；immigrate from；immigrate as a child。','emigrate 强调离开原国家；immigrate 强调进入目的国。同一次搬迁从两端看，可以分别使用这两个词。',('Her parents immigrated to Canada before she was born.','她出生前，父母就移居到了加拿大。'),('He immigrated from Italy as a child.','他小时候从意大利移居而来。'),sources=['https://www.etymonline.com/word/immigrate','https://www.oxfordlearnersdictionaries.com/definition/english/immigrate']),
E('immigration','/ˌɪmɪˈɡreɪʃən/','移民迁入；入境事务；入境检查部门','可以谈人迁进一个国家的现象，也可以谈机场负责检查入境资格的那一关。','immigrate + -ion，-ate 对应 -ation；英语从迁入动词形成过程名词，后来又简称相关主管机关或检查环节。',IMMIGRATE+[['英语 immigrate → immigration','迁入 → 移民迁入现象；入境事务与部门']],'immigration policy 是移民政策；go through immigration 是接受入境检查，旅客不必真的在该国移民定居。这里的机场用法是部门、程序的简称。','immigration policy；immigration officials；go through immigration。','customs 主要检查货物、申报物品；immigration 主要处理人员入境，两道环节常相邻却不同。',('The museum traces the city’s history of immigration.','博物馆追溯了这座城市的移民迁入历史。'),('We waited in line at immigration after landing.','降落后，我们在入境检查处排队等候。'),sources=['https://www.etymonline.com/word/immigration','https://www.oxfordlearnersdictionaries.com/definition/english/immigration']),
E('immigrant','/ˈɪmɪɡrənt/','移入的居民；移民；移民的','从接受地看，一个从别国迁来生活的人。','接拉丁 immigrans、immigrant-，是 immigrare 的现在分词；英语人物名词也可能受法语 immigrant 启发，不只等于英语动词换尾。',IM+[['拉丁语 immigrans / immigrant-；可能经法语 immigrant','正在迁入的形式'],['英语 immigrant','迁入居民；作修饰语时指移民的']],'an immigrant family 是移民家庭；immigrant communities 是移民群体。词本身只描述迁移关系，不告诉你某人的身份手续、经济状况或具体迁移原因。','an immigrant family；recent immigrants；immigrant communities。','emigrant 从原居地看离开的人；immigrant 从目的地看迁来的人。不是两种永远互斥的人群。',('The archive contains letters written by recent immigrants.','档案馆保存了新近移民写的信。'),('The school works closely with immigrant families.','学校与移民家庭保持密切合作。'),sources=['https://www.etymonline.com/word/immigrant','https://www.oxfordlearnersdictionaries.com/definition/english/immigrant']),
E('emigrate','/ˈemɪɡreɪt/','移居国外；从原国家或地区迁出','站在出发地这一边看：离开原来的家乡，去别处长期生活。','拉丁 ex-“向外” + migrare 组成 emigrare；英语可能接分词 emigratus，也可能从更早的 emigration 反构。',EMIGRATE,'emigrate from a country 指从某国迁出；也可说 emigrate to a destination，说明去向。和 immigrate 的关键差别是观察焦点，不是一个能接 to、另一个绝不能接。','emigrate from；emigrate to；decide to emigrate。','leave a country 可以只是出境；emigrate 通常有到别处定居的意思。immigrate 则站在迁入一端。',('The family emigrated from Spain in the 1960s.','这家人在二十世纪六十年代从西班牙迁出。'),('She plans to emigrate to Australia next year.','她计划明年移居澳大利亚。'),sources=['https://www.etymonline.com/word/emigrate','https://www.oxfordlearnersdictionaries.com/definition/english/emigrate']),
E('emigration','/ˌemɪˈɡreɪʃən/','向外移民；移居国外；人口迁出','把离开原居地到别处安家的过程，或一段时间里的迁出趋势当成整体。','来自晚期拉丁 emigratio，接 emigrare；英语名词较早，emigrate 还可能由它反构，不能把顺序一律写成动词到名词。',EMIGRATION,'a wave of emigration 是一波人口外迁；emigration from a region 关注原居地失去哪些居民。可以与目的地的 immigration 描述同一批人的移动。','a wave of emigration；emigration from；patterns of emigration。','immigration 是从接收地看迁入；emigration 是从原居地看迁出；migration 包含更广的移动。',('The exhibition explores a century of emigration from the island.','展览探讨了这座岛一个世纪以来的人口外迁。'),('Economic uncertainty contributed to a new wave of emigration.','经济不确定性促成了新一波移居国外的潮流。'),sources=['https://www.etymonline.com/word/emigration','https://www.oxfordlearnersdictionaries.com/definition/english/emigration']),
E('emigrant','/ˈemɪɡrənt/','移居国外者；迁出居民；移民的〔从出发地看〕','家乡的人在谈那些已经离开、到别处安家的人。','接拉丁 emigrans、emigrant-，是 emigrare 的现在分词；英语名词早于常见动词 emigrate 的记录。',EM+[['拉丁语 emigrans / emigrant- → 英语 emigrant','正在迁出 → 迁居别处的人']],'letters from emigrants 常是从海外寄回家乡的信；emigrant communities 可以在新居住地形成，但命名仍着眼其离乡经历。不是短期游客的普通名称。','an emigrant family；letters from emigrants；emigrant communities。','同一个人，对原居国是 emigrant，对目的国是 immigrant；词首元音也不同：/e/ 与 /ɪ/。',('The museum preserves letters sent home by emigrants.','博物馆保存了移居海外者寄回家乡的信。'),('Many emigrants maintained close ties with their hometowns.','许多移居国外者与故乡保持着密切联系。'),sources=['https://www.etymonline.com/word/emigrant','https://www.oxfordlearnersdictionaries.com/definition/english/emigrant']),
]
DEFERRED={'transmigration':'灵魂迁移等专门宗教哲学或人口术语，暂缓。','remigration':'低频人口迁移术语，通用学习先用 return migration 理解。','transmigrate':'较专门宗教哲学或迁居动词，暂缓。','countermigration':'专门人口流动术语，暂缓。','migrational':'低频形容词，先学 migration、migratory。','remigrant':'低频人口研究人物名词，暂缓。','remigrate':'低频再次迁移动词，暂缓。','transmigrant':'低频专业迁移人物名词，暂缓。','transmigratory':'罕用专业形容词，暂缓。'}
SCAL_ROOT=dict(id='C1266',meaning='梯子、层级、尺度；攀升与调整规模',core='梯子一级一级往上，给了等级、刻度和音阶一个直观画面；换一把尺子或换一个比例，又能缩放图像、调整业务规模。',image='scala 梯子 → scale 刻度、等级、比例、规模；scalaris → scalar 标量；escalade 攀梯 → Escalator 自动扶梯 → escalate 升级 → escalation。',intro='主线是拉丁 scala“梯子、台阶”，与 scandere“攀登”有关。scale 的鱼鳞义、秤义有不同日耳曼近源，本页为掌握这个常用词一并讲清，但不说它们是拉丁 scala 的后代。escalator 先是商标，escalate 后来由它逆构，不按词长猜先后。',forms='scal- 的等级与尺寸义催生 scale、scaling、scalable、scalability。re- 重新设尺度，up/down 可以调尺寸或市场档次。scalar 接古典形容词，数学术语不能只按字面“梯子状”去理解。',branches=[['尺度与数学','scale, scalar, scaling'],['扩展能力与调整','scalable, scalability, rescale, upscale, downscale'],['扶梯与程度升级','escalator, escalate, escalation']],contrasts='大不等于可扩展：large 描述现在，scalable 描述增长时的能力。scale 的鱼鳞、秤、刻度分别核对来源。escalate an issue 可以是上报处理，不一定是把问题恶化。',practice='分别说明 a pay scale、a weighing scale、fish scales 的意思。再用 scalable 与 scalability 描述一个人数增加后仍能正常运作的系统。',words=list(ASSIGN['roots'][62]['family']),exclude={})
FIX_ROOT=dict(id='C0429',meaning='刺入、钉住、固定；修理、词缀与执着',core='先是把东西钉稳；时间可以定住，注意力可以停住，坏掉的东西可以修到正常状态。把一个成分固定到词上，就有了词缀。',image='figere 钉住 → fixus → fix 固定、安排、修好；prae- 在前 → prefix；ad- 附着 → affix；trans- 穿过 → transfix，进而表示看呆、僵住。',intro='拉丁 figere 的分词词干 fix- 是本组核心。不同英语词的近源并不都经过英语 fix：prefix、affix、fixation 有各自古典或法语路线；fixation 还早于 fixate。fixture 的拼写受类似 mixture 的类推影响，不能因此编造一个不存在的拉丁分词。',forms='fix 的 -ed 在 /s/ 后读 /t/，fixed、transfixed 不额外读一个 /ɪd/ 音节。affix 名词前重音、动词后重音；prefix 的动词也常前重音，不套用绝对规则。fixate 常见英美重音有别。',branches=[['把问题处理好、把状态定住','fix, fixed, fixing, fixer, fixable, hotfix'],['固定在位置或日程上','fixture'],['注意力被钉住','fixation, fixate, fixated, transfix, transfixed'],['词语上的附加成分','prefix, suffix, affix']],contrasts='fixated 常是长期、过度的执着；transfixed 更像一时看呆。prefix 在前、suffix 在后，affix 是总称。fixed 是已经固定或修好，fixable 只是能够修好。',practice='用 fix 分别说修锁、定日期、操纵比赛；用 fixation 与 transfixed 区分纠结过去和看烟花出神。',words=list(ASSIGN['roots'][63]['family']),exclude={})
MIGR_ROOT=dict(id='C0737',meaning='迁移、换地方；迁入与迁出',core='同一次搬家，从老家看是迁出，从新家看是迁入；先决定自己站在哪一端观察，就不容易混淆。',image='migrare 换地方 → migrate、migration；in- 向内 → immigrate、immigration、immigrant；ex- 向外 → emigrate、emigration、emigrant。',intro='主线是拉丁 migrare“从一处迁往另一处”。英语 migration、emigration 有独立拉丁名词来源，不能全部排成现代动词加后缀；emigrate 还可能从 emigration 反构。动物、人口和数据都可迁移，但具体方式与边界不同。',forms='im- 是 in- 在 m 前的同化形式，e- 接 ex-“向外”。-ant 常来自古典现在分词，形成迁移者等名称；-ation 表示迁移过程，migratory 说明迁徙习性或相关性质。',branches=[['一般迁移与迁徙','migrate, migration, migrant, migratory, nonmigratory'],['从目的地看迁入','immigrate, immigration, immigrant'],['从原居地看迁出','emigrate, emigration, emigrant']],contrasts='migrant 不必跨国，也不自动说明任何法律身份；immigrant 与 emigrant 是观察方向不同。immigration 在机场可以是入境检查，短期旅客也会经过。nonmigratory 不等于动物从来不移动。',practice='设想一个人从甲国迁往乙国：分别站在甲、乙两国的角度选 emigrant 或 immigrant。再用 migrate 描述鸟和数据，比较词义怎样扩展。',words=[w for w in ASSIGN['roots'][64]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][64]['family'] if w in DEFERRED})
roots=[SCAL_ROOT,FIX_ROOT,MIGR_ROOT]
expected={w for r in ASSIGN['roots'][62:65] for w in r['family'] if w in set(ASSIGN['owned_words']) and w not in DEFERRED}
assert {w['word'] for w in W}==expected,({w['word'] for w in W}-expected,expected-{w['word'] for w in W})
assert len(W)==len({w['word'] for w in W})
assert all(len(w['examples'])>=2 and all(len(e)==2 and all(e) for e in w['examples']) for w in W)
